((root,factory)=>{const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.TrigEquationLesson=api;})(typeof window==='undefined'?globalThis:window,()=>{'use strict';const eps=1e-10;function value(kind,x,b=1){const y=Math[kind](b*x);return Math.abs(y)<1e-12?0:y;}function roots(kind,c,b,lo,hi,rightClosed=false){if(!['sin','cos','tan'].includes(kind)||!Number.isFinite(c)||!(b>0)||hi<lo)return [];if(kind!=='tan'&&Math.abs(c)>1)return [];const alpha=kind==='sin'?Math.asin(c):kind==='cos'?Math.acos(c):Math.atan(c),seeds=kind==='sin'?[alpha,Math.PI-alpha]:kind==='cos'?[alpha,-alpha]:[alpha],period=kind==='tan'?Math.PI:2*Math.PI,found=[];for(const seed of seeds){const first=Math.ceil((b*lo-seed)/period-eps),last=Math.floor((b*hi-seed)/period+eps);for(let k=first;k<=last;k++){let x=(seed+k*period)/b;if(Math.abs(x-lo)<eps)x=lo;if(Math.abs(x-hi)<eps)x=hi;if(x>=lo&&(rightClosed?x<=hi:x<hi)&&!found.some(y=>Math.abs(x-y)<eps))found.push(Object.is(x,-0)?0:x);}}return found.sort((a,b)=>a-b);}function point(x,y,lo,hi){return {x:48+562*(x-lo)/(hi-lo),y:145-120*y/1.75};}function curve(kind,b,lo,hi){return Array.from({length:601},(_,i)=>{const x=lo+(hi-lo)*i/600;return point(x,value(kind,x,b),lo,hi);});}return {value,roots,point,curve};});